<template><ForgeDialog title="URL parser" description="Inspect URL components and query parameters." eyebrow="WORKSPACE / NETWORK" wide @close="emit('close')"><div class="url-panel"><input v-model="value" autofocus placeholder="https://example.com:8443/path?query=value#section" /><p v-if="error" class="forge-alert forge-alert--error">{{ error }}</p><p v-if="copyStatus" role="status">{{ copyStatus }}</p><div v-if="parsed" class="url-grid"><div v-for="part in parts" :key="part.key"><span>{{ part.label }} <button class="text-button" @click="copy(part.value)">Copy</button></span><code>{{ part.value || '—' }}</code></div></div><div v-if="parsed && params.length" class="url-params"><b>Query parameters</b><div v-for="param in params" :key="param.key+param.value"><code>{{ param.key }}</code><code>{{ param.value }}</code></div></div></div></ForgeDialog></template>
<script setup lang="ts">
import { computed, ref } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
const copyStatus = ref('')
const copy = async (text: string) => { try { await navigator.clipboard.writeText(text); copyStatus.value = 'Copied.' } catch { copyStatus.value = 'Clipboard access failed.' } }
const emit=defineEmits<{close:[]}>(); const value=ref('https://example.com:8443/path?query=value#section'); const parsed=computed(()=>{try{return new URL(value.value)}catch{return undefined}}); const error=computed(()=>value.value&&!parsed.value?'Enter a valid URL.':''); const parts=computed(()=>{const u=parsed.value;return u?[{key:'href',label:'Href',value:u.href},{key:'origin',label:'Origin',value:u.origin},{key:'protocol',label:'Protocol',value:u.protocol},{key:'username',label:'Username',value:u.username},{key:'password',label:'Password',value:u.password},{key:'host',label:'Host',value:u.host},{key:'hostname',label:'Hostname',value:u.hostname},{key:'port',label:'Port',value:u.port},{key:'pathname',label:'Path',value:u.pathname},{key:'search',label:'Search',value:u.search},{key:'hash',label:'Hash',value:u.hash}]:[]}); const params=computed(()=>parsed.value?[...parsed.value.searchParams.entries()].map(([key,value])=>({key,value})):[])
</script>
<style scoped>.url-panel{display:grid;gap:12px}.url-panel>input{padding:10px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:12px var(--pqt-font-mono)}.url-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.url-grid div{display:grid;gap:4px;padding:9px;border:1px solid var(--pqt-border);border-radius:7px}.url-grid span,.url-params>b{color:var(--pqt-text-muted);font-size:10px;text-transform:uppercase}.url-grid code,.url-params code{overflow-wrap:anywhere;color:var(--pqt-text);font:11px var(--pqt-font-mono)}.url-params{display:grid;gap:7px}.url-params div{display:grid;grid-template-columns:1fr 1fr;gap:7px;padding:7px 9px;background:var(--pqt-canvas);border-radius:5px}</style>
